import CryptoKit
import Foundation

/// Describes the proxy core shipped inside the application bundle.
/// Generated by `scripts/fetch-core.sh`; never edited by hand.
public struct CoreManifest: Codable, Sendable, Equatable {
    public var name: String
    public var version: String
    public var archs: [String]
    public var archive: String
    public var sha256: String
    public var size: Int
    public var source: String?

    public static func load(from url: URL) throws -> CoreManifest {
        try JSONDecoder().decode(CoreManifest.self, from: Data(contentsOf: url))
    }

    /// Streaming SHA-256 of an arbitrary file.
    public static func sha256(of fileURL: URL) throws -> String {
        let handle = try FileHandle(forReadingFrom: fileURL)
        defer { try? handle.close() }
        var hasher = SHA256()
        while let chunk = try handle.read(upToCount: 4 << 20), !chunk.isEmpty {
            hasher.update(data: chunk)
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }
}
